#!/usr/bin/env python3
# h264enc-template.py TRACEDIR OUT.h: NVIDIA's H.264 ME / MD / quant control blocks (0x100 bytes each, at 0x300 / 0x400 /
# 0x500 of its picture setup) for IDR, P and B pictures, from a trace of ffmpeg h264_nvenc -preset p4 -bf 2
# (docs/traces/bframes-linux/hb2s: exec1 IDR, exec2 P, exec3 B). They do not depend on the picture size. Also the
# driver's lookahead pictures (QP 40 at a quarter of the size; docs/traces/quality-linux/vla exec1 IDR, exec2 P; T7.09).
#   h264enc-template.py docs/traces/bframes-linux/hb2s src/h264enctmpl.h [docs/traces/quality-linux/vla]
import sys
d, out = sys.argv[1], sys.argv[2]
la = sys.argv[3] if len(sys.argv) > 3 else 'docs/traces/quality-linux/vla'
def blk(k, off, t=None): return open('%s/dump/exec%d-710.bin' % (t or d, k), 'rb').read()[off:off + 0x100]
def arr(name, data):
    rows = [', '.join('0x%02x' % b for b in data[i:i + 16]) for i in range(0, len(data), 16)]
    return 'static const unsigned char %s[256] = {\n    %s\n};\n' % (name, ',\n    '.join(rows))
s = '// h264enctmpl.h: generated by scripts/h264enc-template.py from docs/traces/bframes-linux/hb2s (NVIDIA Linux driver,\n'
s += '// h264_nvenc -preset p4 -bf 2): ME / MD / quant controls for IDR, P and B pictures; the lookahead pictures\' from\n'
s += '// docs/traces/quality-linux/vla.\n#pragma once\n'
for name, k in (('idr', 1), ('p', 2), ('b', 3)):
    s += arr('h264_tmpl_me_' + name, blk(k, 0x300)) + arr('h264_tmpl_md_' + name, blk(k, 0x400))
s += arr('h264_tmpl_q', blk(1, 0x500))
s += '// lookahead pictures (T7.09)\n'
for name, k in (('idr', 1), ('p', 2)):
    s += arr('h264_la_me_' + name, blk(k, 0x300, la)) + arr('h264_la_md_' + name, blk(k, 0x400, la))
s += arr('h264_la_q', blk(2, 0x500, la))
open(out, 'w').write(s)
